from pathlib import Path
from html import escape
p=Path(__file__).resolve().parents[1]/'assets/ai-course/adult'
def svg(name,title,subtitle,body):
 (p/name).write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="700" viewBox="0 0 1200 700" role="img" aria-label="{escape(title)}"><rect width="1200" height="700" fill="#f5f6f3"/><g font-family="Arial,sans-serif" fill="#17202a"><text x="60" y="70" font-size="17" letter-spacing="3" fill="#2458ea">TIMECODE / КУЛЬТУРНЫЙ КОД</text><text x="60" y="139" font-size="42" font-weight="bold">{escape(title)}</text><text x="60" y="184" font-size="23" fill="#566171">{escape(subtitle)}</text>{body}<text x="60" y="668" font-size="17" fill="#566171">Редакционный учебный образец · проверяйте свой результат</text></g></svg>''')
def boxes(items):
 out=''
 for i,(top,big,small) in enumerate(items):
  x=60+(i%2)*555;y=225+(i//2)*190
  out+=f'<rect x="{x}" y="{y}" width="525" height="164" rx="12" fill="white" stroke="#d4dce4"/><rect x="{x}" y="{y}" width="7" height="164" rx="3" fill="{["#2458ea","#16806d","#bd5e32","#8145ad"][i]}"/><text x="{x+25}" y="{y+39}" font-size="19" fill="#566171">{escape(top)}</text><text x="{x+25}" y="{y+84}" font-size="29" font-weight="bold">{escape(big)}</text><text x="{x+25}" y="{y+125}" font-size="20">{escape(small)}</text>'
 return out
svg('rkfo.svg','Сначала задача. Затем — РКФО.','«Составь карточку моей студии керамики»',boxes([('Р / РОЛЬ','Методист Дома культуры','С какой профессиональной позиции'),('К / КОНТЕКСТ','Дети 7–10 лет, новички','Для кого, где, с какими ресурсами'),('Ф / ФОРМАТ','Карточка + пост до 500 знаков','Какие разделы и в каком виде'),('О / ОГРАНИЧЕНИЯ','Без клише и выдуманных фактов','Тон, объём и границы задания')]))
svg('hours.svg','72 академических ≠ 72 обычных часа','Учебный пример КТП. Продолжительность своего занятия уточните в ДК.',boxes([('УЧЕБНЫЕ НЕДЕЛИ','36 × 2 занятия','72 встречи за учебный год'),('ПРОДОЛЖИТЕЛЬНОСТЬ','72 × 45 минут','3 240 минут занятий'),('АКАДЕМИЧЕСКИЕ ЧАСЫ','3 240 ÷ 45 = 72','Один академический час = 45 минут'),('АСТРОНОМИЧЕСКИЕ ЧАСЫ','3 240 ÷ 60 = 54','Один астрономический час = 60 минут')]))
svg('table.svg','Не перепечатываем. Переносим.','Копируем только таблицу. Затем проверяем ячейки и суммы.',boxes([('1 / ЧАТ','Согласованная таблица','36 недель, правильные единицы'),('2 / ЕСЛИ СТОЛБЦЫ СЪЕХАЛИ','Попросить TSV','Колонки разделены табуляцией'),('3 / РЕДАКТОР','Вставить в A1','При необходимости импорт текста'),('4 / ПРОВЕРКА','Строки и часы сошлись?','Сохранить рабочий файл и копию')]))
svg('visual-brief.svg','«Красиво» — это ещё не задание','Пример: иллюстрация для афиши студии керамики.',boxes([('ОБЪЕКТ','Руки лепят вазу','Один понятный сюжет'),('СТИЛЬ','Предметная фотография','Светлый стол, естественный свет'),('КОМПОЗИЦИЯ','Вертикально, формат 4:5','Верх свободен под заголовок'),('ОГРАНИЧЕНИЯ','Без надписей и логотипов','Проверить анатомию и детали')]))
svg('attendance.svg','Пусто — не значит «отсутствовал»','Учебная логика. Сначала статусы, потом формула.',boxes([('ПРИСУТСТВОВАЛ','1','Подтверждённая отметка'),('ОТСУТСТВОВАЛ','0','Подтверждённая отметка'),('НЕТ ДАННЫХ','Пустая ячейка','Не включаем в известные отметки'),('ПРИМЕР: 1, 1, 0, ПУСТО','2 ÷ 3 ≈ 66,7%','По известным отметкам, не за весь год')]))
svg('report.svg','Тон меняется. Факты остаются.','Учебная викторина: 20 участников, 2 раунда, одна игра не состоялась.',boxes([('ЗАМЕТКА','«Два раунда, четыре команды»','Записываем конкретные действия'),('ОТЧЁТ','«Проведена викторина…»','Форма деловая, факты те же'),('ЖУРНАЛ','Тема + действия + время','Короткая запись о проведённом'),('ПОСТ','«Команды спорили о героях»','Живой язык без приписок')]))
svg('slides.svg','Шесть экранов, которые ведут занятие','На слайде один смысл. Инструкция крупнее украшений.', ''.join(f'<rect x="{60+(i%3)*365}" y="{230+(i//3)*193}" width="340" height="166" rx="10" fill="{["#202a37","#e6edff","#d5eee5","#f4e0d1","#e7e1f3","#202a37"][i]}"/><text x="{82+(i%3)*365}" y="{277+(i//3)*193}" font-size="20" fill="{("white" if i in (0,5) else "#2458ea")}">0{i+1} / 06</text><text x="{82+(i%3)*365}" y="{335+(i//3)*193}" font-size="29" fill="{("white" if i in (0,5) else "#17202a")}">{t}</text>' for i,t in enumerate(['Вопрос-зацепка','Понятный пример','Правила игры','Практическая проба','Показ и сравнение','Что получилось?'])))
