svg('poster.svg','Афиша: текст остаётся у вас под контролем','Учебный макет компоновки, не готовый анонс мероприятия.', '<rect x="290" y="215" width="620" height="410" rx="10" fill="#e6edff"/><text x="340" y="279" font-size="40" font-weight="bold">СТУДИЯ КЕРАМИКИ</text><text x="340" y="319" font-size="24">Дети [возраст] · набор в группу</text><rect x="340" y="349" width="520" height="165" rx="8" fill="#c77954"/><path d="M540 375H660V410L695 470Q700 490 674 495H526Q500 490 505 470L540 410Z" fill="#f4d5bb"/><text x="340" y="560" font-size="23">[Проверенные дата и место]</text><text x="340" y="597" font-size="23">Запись: [ваш контакт]</text>')
